CREATE DATABASE IF NOT EXISTS sammy_tech_store CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sammy_tech_store;
CREATE TABLE IF NOT EXISTS administrators (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, sku VARCHAR(60) NOT NULL UNIQUE, short_description VARCHAR(255) NOT NULL, image_path VARCHAR(255) NULL, price DECIMAL(12,2) NOT NULL, stock_quantity INT NOT NULL DEFAULT 0, reorder_level INT NOT NULL DEFAULT 5, featured TINYINT(1) NOT NULL DEFAULT 0, status ENUM('active','draft','out_of_stock') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id INT UNSIGNED NULL, order_number VARCHAR(30) NOT NULL UNIQUE, customer_name VARCHAR(150) NOT NULL, phone VARCHAR(50) NOT NULL, alternative_phone VARCHAR(50) NULL, email VARCHAR(150) NULL, delivery_method ENUM('pickup','delivery') NOT NULL DEFAULT 'pickup', delivery_area VARCHAR(100) NULL, delivery_address VARCHAR(255) NULL, payment_method ENUM('cash','mobile_money','bank_transfer') NOT NULL DEFAULT 'cash', payment_status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending', status ENUM('new','confirmed','processing','ready','completed','cancelled') NOT NULL DEFAULT 'new', subtotal DECIMAL(12,2) NOT NULL DEFAULT 0, delivery_charge DECIMAL(12,2) NOT NULL DEFAULT 0, total_amount DECIMAL(12,2) NOT NULL, stock_deducted_at DATETIME NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, product_name VARCHAR(150) NOT NULL, quantity INT UNSIGNED NOT NULL DEFAULT 1, unit_price DECIMAL(12,2) NOT NULL, CONSTRAINT fk_item_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_item_product FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, phone VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(150) NULL, alternative_phone VARCHAR(50) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS addresses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id INT UNSIGNED NOT NULL, area VARCHAR(100) NOT NULL, address_line VARCHAR(255) NOT NULL, landmark VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id INT UNSIGNED NOT NULL, payment_method ENUM('cash','mobile_money','bank_transfer') NOT NULL, amount DECIMAL(12,2) NOT NULL, currency ENUM('USD','SSP') NOT NULL DEFAULT 'USD', exchange_rate DECIMAL(12,4) NULL, payment_status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending', reference_number VARCHAR(100) NULL, proof_path VARCHAR(255) NULL, confirmed_by INT UNSIGNED NULL, confirmed_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (confirmed_by) REFERENCES administrators(id));
CREATE TABLE IF NOT EXISTS installation_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id INT UNSIGNED NOT NULL, service_type VARCHAR(100) NOT NULL, location VARCHAR(255) NOT NULL, preferred_date DATE NULL, installation_charge DECIMAL(12,2) NOT NULL DEFAULT 0, request_status ENUM('new','scheduled','in_progress','completed','cancelled') NOT NULL DEFAULT 'new', notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS stock_movements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, order_id INT UNSIGNED NULL, movement_type ENUM('in','out','adjustment','restored') NOT NULL, quantity INT NOT NULL, notes VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (product_id) REFERENCES products(id), FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL, ip_address VARCHAR(45) NOT NULL, attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_login_attempts (username, ip_address, attempted_at));
